export function getReceiptImageUrl(expense) {
  if (expense.storage_provider === 'r2' && expense.drive_file_id) {
    return `${process.env.R2_PUBLIC_URL}/${expense.drive_file_id}`;
  }
  return expense.receipt_image_url;
}
